// prefixes: registry ROWS → nodeve.yaml's prefix map. A CURIE prefix IS a
// registry slug and its expansion IS that row's node.url — the ONE source, so
// the block is fully derived, never hand-authored. Our own namespaces
// (nodeve/node) are registry rows too, published by Amorella. Prefixes live on
// the root because the SQL generators' loader resolves imported CURIEs against
// it (see shared.yaml). Regenerated by `generate`; re-styled by format.ts.
import { abs, readDoc, readYaml, serializeYaml, write, yamlNames } from '../src/io.ts';

const registry: Record<string, string> = {};
for (const name of yamlNames(abs('data/registry'))) {
	const url = readYaml<{ node?: { url?: string } }>(abs(`data/registry/${name}`)).node?.url;
	if (url) registry[name.replace(/\.yaml$/, '')] = url;
}

const prefixMap = Object.fromEntries(Object.entries(registry).sort());
const doc = readDoc(abs('linkml/nodeve.yaml'));
doc.set('prefixes', prefixMap);
write(abs('linkml/nodeve.yaml'), serializeYaml(doc));
console.log(`${Object.keys(prefixMap).length} prefixes → linkml/nodeve.yaml`);
